# Define a function for generating a secure hashed password
def generate_hash(password):
  return hashlib.sha256(password.encode()).hexdigest()

# Define a function for checking if the provided password matches the stored password
def check_password(stored_password, provided_password):
  return stored_password == generate_hash(provided_password)

