        perror("Error opening input file");
        return 1;
    }

    // Allocate memory for the buffer
    char *buffer = malloc(sizeof(char) * 1024);
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for buffer\n");
        return 1;
    }

    // Read the contents of the file into the buffer
    size_t bytes_read = fread(buffer, sizeof(char), 1024, input_file);
    if (bytes_read == 0) {
        fprintf(stderr, "Error reading from file\n");
        return 1;
    }

    // Calculate the checksum of the buffer
    unsigned int checksum = 0;
    for (int i = 0; i < bytes_read; i++) {
        checksum += (unsigned char)buffer[i];
    }

    // If the checksum is 0, then the buffer is empty
    if (checksum == 0) {
        fprintf(stderr, "Buffer is empty\n");
        return 1;
    }

    // Save the number of bytes read and the checksum to another file
    FILE *output_file = fopen("output.txt", "w");
    if (output_file == NULL) {
        perror("Error opening output file");
        return 1;
    }
    fprintf(output_file, "%zu %u\n", bytes_read, checksum);
