// Function to execute a command and return its output as a string
char* execute_command(const char* command) {
    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to run command\n");
        exit(1);
    }

    // Read the output of the command into a string
    char* buffer = malloc(BUFSIZ);
    while (fgets(buffer, BUFSIZ, fp) != NULL) {
        printf("%s", buffer);
    }

    // Close the file and return the output as a string
    pclose(fp);
    return buffer;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s username\n", argv[0]);
        exit(1);
    }

    // Get the username from the command line arguments
    const char* username = argv[1];

    // Execute the command to print the user information
    char* output = execute_command("cat /etc/passwd | grep %s", username);
    printf("%s\n", output);

    return 0;
}
