int main(int argc, char *argv[]) {
    // Check if the user has passed in an argument
    if (argc == 1) {
        printf("Usage: ./trim_trailing_whitespace [argument]\n");
        return 0;
    }

    // Get the input string and trim any trailing whitespace characters
    char *input = argv[1];
    while (isspace(input[strlen(input) - 1])) {
        input[strlen(input) - 1] = '\0';
    }

    // Print the trimmed string to the console
    printf("%s\n", input);

    return 0;
}
```
