from urllib.parse import quote_plus

def decorator(func):
    def wrapper(*args, **kwargs):
        username = kwargs["username"]
        escaped_username = escape(username)
        return func(escaped_username)
    return wrapper

@decorator
def hello(username):
    return f"Hello {username}!"

def escape(s):
    return quote_plus(s, safe="")

